#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / "upstream"
client_probe = ROOT / "fabric/src/main/java/org/valkyrienskies/mod/fabric/client/GateEClientProbe.java"
source = client_probe.read_text(encoding="utf-8")

field_anchor = '''    private static long ticks;\n'''
field_replacement = '''    private static long ticks;\n    private static boolean fixtureClientNormalized;\n'''
if "fixtureClientNormalized" not in source:
    if field_anchor not in source:
        raise SystemExit("Phase 61 could not find Gate E static tick field anchor")
    source = source.replace(field_anchor, field_replacement, 1)

candidate_anchor = '''            var carriageCandidates = client.level.getEntitiesOfClass(\n                    Entity.class,\n                    player.getBoundingBox().inflate(64.0),\n                    entity -> "create:carriage_contraption".equals(\n                            BuiltInRegistries.ENTITY_TYPE.getKey(entity.getType()).toString()));\n            StringBuilder candidateState = new StringBuilder();'''

candidate_replacement = '''            var carriageCandidates = client.level.getEntitiesOfClass(\n                    Entity.class,\n                    player.getBoundingBox().inflate(64.0),\n                    entity -> "create:carriage_contraption".equals(\n                            BuiltInRegistries.ENTITY_TYPE.getKey(entity.getType()).toString()));\n\n            // Phase 60 normalizes the integrated-server ServerPlayer, but setPos() is not\n            // guaranteed to update LocalPlayer before the automatic train starts moving.\n            // Mirror the exact fixture-only normalization on the client once so Create's\n            // actual local-player collision path is tested from real carriage geometry.\n            if (!fixtureClientNormalized && !carriageCandidates.isEmpty()) {\n                Entity bestCarriage = null;\n                Vec3 bestWorldTop = null;\n                double bestDistanceSq = Double.POSITIVE_INFINITY;\n                try {\n                    for (Entity fixtureCandidate : carriageCandidates) {\n                        java.lang.reflect.Method getContraptionFixture = fixtureCandidate.getClass().getMethod("getContraption");\n                        Object fixtureContraption = getContraptionFixture.invoke(fixtureCandidate);\n                        if (fixtureContraption == null) continue;\n                        java.lang.reflect.Method getBlocksFixture = fixtureContraption.getClass().getMethod("getBlocks");\n                        Object fixtureBlocksObject = getBlocksFixture.invoke(fixtureContraption);\n                        if (!(fixtureBlocksObject instanceof Map<?, ?> fixtureBlocks)) continue;\n                        java.lang.reflect.Method toGlobalFixture = null;\n                        for (java.lang.reflect.Method method : fixtureCandidate.getClass().getMethods()) {\n                            if (!method.getName().equals("toGlobalVector") || method.getParameterCount() != 2) continue;\n                            Class<?>[] p = method.getParameterTypes();\n                            if (p[0] == Vec3.class && p[1] == float.class) {\n                                toGlobalFixture = method;\n                                break;\n                            }\n                        }\n                        if (toGlobalFixture == null) continue;\n                        for (Object key : fixtureBlocks.keySet()) {\n                            if (!(key instanceof net.minecraft.core.BlockPos pos)) continue;\n                            Vec3 localTop = new Vec3(pos.getX() + 0.5, pos.getY() + 1.0, pos.getZ() + 0.5);\n                            Vec3 worldTop = (Vec3) toGlobalFixture.invoke(fixtureCandidate, localTop, 0.0f);\n                            double dx = worldTop.x - player.getX();\n                            double dy = worldTop.y - player.getY();\n                            double dz = worldTop.z - player.getZ();\n                            double distanceSq = dx * dx + dy * dy + dz * dz;\n                            if (distanceSq < bestDistanceSq) {\n                                bestDistanceSq = distanceSq;\n                                bestWorldTop = worldTop;\n                                bestCarriage = fixtureCandidate;\n                            }\n                        }\n                    }\n                    if (bestWorldTop != null) {\n                        fixtureClientNormalized = true;\n                        if (bestDistanceSq > 4.0) {\n                            player.setPos(bestWorldTop.x, bestWorldTop.y + 0.05, bestWorldTop.z);\n                            player.setDeltaMovement(Vec3.ZERO);\n                            LOGGER.info(\n                                "GATE_E_FIXTURE_CLIENT_REPOSITIONED old_distance_sq={} target={},{},{} carriage_pos={},{},{}",\n                                bestDistanceSq, bestWorldTop.x, bestWorldTop.y + 0.05, bestWorldTop.z,\n                                bestCarriage == null ? Double.NaN : bestCarriage.getX(),\n                                bestCarriage == null ? Double.NaN : bestCarriage.getY(),\n                                bestCarriage == null ? Double.NaN : bestCarriage.getZ());\n                            return;\n                        } else {\n                            LOGGER.info("GATE_E_FIXTURE_CLIENT_ALREADY_ON_GEOMETRY distance_sq={}", bestDistanceSq);\n                        }\n                    }\n                } catch (ReflectiveOperationException | RuntimeException exception) {\n                    LOGGER.info("GATE_E_FIXTURE_CLIENT_NORMALIZE_ERROR type={}", exception.getClass().getSimpleName());\n                }\n            }\n\n            StringBuilder candidateState = new StringBuilder();'''

if "GATE_E_FIXTURE_CLIENT_REPOSITIONED" not in source:
    if candidate_anchor not in source:
        raise SystemExit("Phase 61 could not find Gate E carriage candidate anchor")
    source = source.replace(candidate_anchor, candidate_replacement, 1)

client_probe.write_text(source, encoding="utf-8")
print("Phase 61: mirrored CI fixture normalization onto LocalPlayer before Create contact/carry measurement so server and client begin on the same real carriage block; harness-only, no production physics changes")
